import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";
import * as ENV from "../config";

// =============================
// FETCH MESSAGES (REST)
// =============================
export const fetchMessages = createAsyncThunk(
  "chat/fetchMessages",
  async (applicationId, thunkAPI) => {
    try {
      const res = await axios.get(`${ENV.SERVER_URL}/chat/${applicationId}`);
      return res.data;
    } catch (err) {
      return thunkAPI.rejectWithValue("Failed to load messages");
    }
  }
);

// =============================
// SEND MESSAGE (REST)
// =============================
export const sendMessage = createAsyncThunk(
  "chat/sendMessage",
  async (data, thunkAPI) => {
    try {
      const res = await axios.post(`${ENV.SERVER_URL}/chat/send`, data);
      return res.data;
    } catch (err) {
      return thunkAPI.rejectWithValue("Failed to send message");
    }
  }
);

// =============================
// SLICE
// =============================
const chatSlice = createSlice({
  name: "chat",
  initialState: {
    messages: [],
    isLoading: false,
    isError: false,
  },
  reducers: {
    // Used for live socket messages
    addSocketMessage: (state, action) => {
      state.messages.push(action.payload);
    },
  },
  extraReducers: (builder) => {
    builder
      // FETCH
      .addCase(fetchMessages.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(fetchMessages.fulfilled, (state, action) => {
        state.messages = action.payload;
        state.isLoading = false;
      })
      .addCase(fetchMessages.rejected, (state) => {
        state.isLoading = false;
        state.isError = true;
      })

      // SEND
      .addCase(sendMessage.fulfilled, (state, action) => {
        state.messages.push(action.payload);
      });
  },
});

export const { addSocketMessage } = chatSlice.actions;
export default chatSlice.reducer;
